import { Component, Input } from '@angular/core';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { filedataRes } from '../../../interfaces/myfile.interface';
import { hightlightModeType } from '../../../../rt/interfaces/feed.interface';
import { IconComponent } from "../../icon/icon.component";

@Component({
  selector: 'preview-page-range',
  standalone: true,
  imports: [IconComponent],
  templateUrl: './preview-page-range.component.html',
  styleUrl: './preview-page-range.component.scss'
})
export class PreviewPageRangeComponent {



  isLoaded: boolean = false;
  cPath: any;

  @Input() activeFile: filedataRes;

  @Input() nCaseid: string;
  @Input() nSectionid: string;


  @Input() hightlightMode: hightlightModeType;


  constructor(private cf: CommonfunctionService) { }


  async ngOnInit() {
    this.updatePath();

  }

  closePreview() {

  }

  updatePath() {
    if (this.activeFile) {
      const path: any = this.cf.senitizeUrl(this.activeFile.cPath, this.activeFile.nBundledetailid, this.nCaseid, true, this.hightlightMode, 1, null,
        null, null, null, null, null, null, null, false, null, this.nSectionid, null, null, null);
      if (path != this.cPath) {
        this.cPath = path
      }
    }

    if (this.cPath) {
      this.isLoaded = true;
    }
    // this.cdr.detectChanges();
  }

}
