import { ChangeDetectorRef, Component, ElementRef, EventEmitter, HostListener, Input, Output, QueryList, SimpleChanges, ViewChildren, OnInit, OnDestroy, AfterViewInit, OnChanges } from '@angular/core';
import { bundleDetailRes, filedataReq, filedataRes } from '../../../interfaces/myfile.interface';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { PdfComponent } from '../../../../pdf/components/pdf/pdf.component';
import { SelectedDocsComponent } from '../selected-docs/selected-docs.component';
import { MatMenuModule } from '@angular/material/menu';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { DocInfo, highlightModeType, toolEvents, PdfEvents } from '../../../../pdf/interfaces/pdf.interface';
import { MatTooltipModule } from '@angular/material/tooltip';
import { tabmodel } from '../../../../realtime/models/annotation.interface';
import { IndividualService } from '../../../../userpanel/services/individual/individual.service';
import { DocumentTab } from '../../../../userpanel/interfaces/individual.interface';
import { environment } from '../../../../../environments/environment';
import { presentSetupData } from '../../../../presentation/interfaces/presentsetup';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { BroadcastingService } from '../../../../core/services/broadcasting/broadcasting.service';
import { advanceFiler } from '../../../../userpanel/interfaces/advance-search.interface';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { PageLinkToolComponent } from "../page-link-tool/page-link-tool.component";
import { PdfDataService } from '../../../../pdf/service/pdf-data.service';
import { pageLinkToolEvent } from '../../../interfaces/preview.interface';
@Component({
  selector: 'preview',
  standalone: true,
  imports: [CommonModule, PdfComponent, ButtonComponent, IconComponent, SelectedDocsComponent, MatMenuModule, MatTooltipModule, PageLinkToolComponent],
  templateUrl: './preview.component.html',
  styleUrl: './preview.component.scss'
})
export class PreviewComponent implements OnInit, OnDestroy, AfterViewInit, OnChanges {
  openPdfInNewTab() {
    // Store selected text context in localStorage before opening PDF in new tab (fact-table approach)
    const detail = this.sidebarSingleFile || this.activeFile;
    let page = 1;
    let nFSid = detail?.nFSid || detail?.jLinktype?.nFSid || null;
    // Store selected text if present
    const selectedText = detail?.jOTexts || detail?.jOT || detail?.jTexts || null;
    if (selectedText && detail?.nBundledetailid) {
      try {
        localStorage.setItem(`pdf_selected_text_${detail.nBundledetailid}`, JSON.stringify(selectedText));
      } catch (e) { /* ignore quota errors */ }
    }
    if (detail?.jLinktype) {
      if (detail.jLinktype?.nPage) {
        page = detail.jLinktype.nPage;
      } else if (detail.jLinktype?.pages?.length) {
        page = detail.jLinktype.pages[0];
      } else if (detail.jLinktype?.start > 1) {
        page = detail.jLinktype.start;
      }
    }
    if (detail?.nBundledetailid && this.nCaseid) {
      this.cf.openHyperLinkFile(detail.nBundledetailid, this.nCaseid, null, null, false, page, null, nFSid);
    }
  }
  @ViewChildren('embeddedIframe') embeddedIframes: QueryList<ElementRef>;
  @Input() isMyfile: boolean = false;
  @Input() viewlist: bundleDetailRes[] = [];
  @Input() changeP: boolean = false;
  @Input() nCaseid: string;
  @Input() rightpanelwidth: number;
  @Input() isLink: highlightModeType = null;
  @Input() selectedDocuments: any[] = [];
  @Input() isChooser: boolean = false;
  @Input() nPage: number = 1;
  @Input() nSectionid: any;
  @Input() activesectiontype: any;
  @Input() previewMode: boolean = false;
  @Output() OnFileSelected = new EventEmitter<any>();
  @Output() changePreview = new EventEmitter<boolean>();
  @Output() OnEvent = new EventEmitter<any>();
  @Input() isRealtime: boolean = false;
  @Input() tabBox: tabmodel | null = null;
  @Input() isadmin: boolean = false;
  @Input() isIndividual: boolean = false;
  // Allow direct PDF preview for sidebar use
  @Input() sidebarSingleFile: any = null;
  activeFile: filedataRes;
  cPath: any;
  currentFiletype: any;
  viewSelection: boolean = false;
  confirmcancel: boolean = false;
  nonsupport: boolean = false;
  hidemsg: boolean = false;
  isSaving: boolean = false;
  @Input() jFilter: advanceFiler;

  @Input() presentSession: presentSetupData | null = null;

  viewChoosen: boolean = false;
  isLoaded: boolean = false;
  private readonly openedWindow: Window | null = null;

  private activePage: number = 1;

  @Input() isPropertiesPermission: boolean = true;
  @Output() OnCloseEvent = new EventEmitter<any>();

  pageRangeTextSelectionData: DocInfo;

  @HostListener('window:message', ['$event'])
  onPdf = (event: MessageEvent) => {
    try {
      if (event.origin !== globalThis.location.origin || !event.data?.identity) {
        return;
      }
      // Handle CLOSE_REALTIME and SHARE events
      const msgEvent = event.data?.message?.event;
      if (msgEvent === PdfEvents.CLOSE_REALTIME) {
        this.OnEvent.emit(event.data?.message);
        return;
      }
      if (msgEvent === PdfEvents.SHARE) {
        const ind = this.viewlist.findIndex(view => view.nBundledetailid === this.activeFile?.nBundledetailid);
        if (ind > -1) {
          this.OnEvent.emit({ event: PdfEvents.SHARE, data: this.activeFile.nBundledetailid, nBundleid: this.viewlist[ind].nBundleid });
        }
        return;
      }
      // Handle realtime events
      if (this.isRealtime) {
        const data: toolEvents = event.data.message;
        if (data.event === PdfEvents.OPEN_INDIVIDUAL) {
          this.cf.openHyperLinkFile(event.data.identity, this.nCaseid, null, null, null, (data?.data?.nPageno || this.nPage || 1), null, null, null, null, this.activesectiontype);
        } else if (data.event === PdfEvents.OPEN_HYPERLINK_FILE) {
          this.cf.openHyperLinkFile(data.data.nBundledetailid, this.nCaseid, null, (data?.data?.nPageno || this.nPage || 1));
        }
      }
      // Find the file in viewlist
      const index: number = this.viewlist.findIndex(a => a.nBundledetailid === event.data.identity);
      if (index === -1) return;
      const x: bundleDetailRes = this.viewlist[index];
      if (x) {
        const data: toolEvents = event.data.message;
        if (data.event === 'LINK-ADDED-DOC') {
          if (data.data?.texts?.length && data.data.texts[0] !== '') {
            this.pageRangeTextSelection(data.data);
          } else if (data.data) {
            this.pageRangeTextSelection(data.data);
          } else {
            this.pageRangeTextSelection(null);
            // Optionally log or handle null data
          }
        } else if (data.event === PdfEvents.OPEN_INDIVIDUAL) {
          if (this.isMyfile) {
            this.cf.openHyperLinkFile(x.nBundledetailid, this.nCaseid, null, data?.data?.jFilter, x.cIsindex, this.nPage);
          }
          if (this.isChooser && !this.isLink) {
            this.openDocumentInChooser(x);
          }
          // Handle double-click for sidebar single file
          if (this.sidebarSingleFile) {
            this.openPdfInNewTab();
          }
        } else if (data.event === PdfEvents.OPEN_HYPERLINK_FILE) {
          this.tost.error('Tip: Open Master Index in full tab to use hyperlinks.');
        }
        if (data.event === PdfEvents.CURRENT_PAGE) {
          this.activePage = data?.data?.currentPage;
        }
      }
    } catch (error) {
      // Properly handle/log the error
      console.error('Error in onPdf handler:', error);
    }
  }

  constructor(
    private readonly myfileS: MyfileService,
    private readonly individualService: IndividualService,
    private readonly cdr: ChangeDetectorRef,
    private readonly cf: CommonfunctionService,
    private readonly SSservice: SecureStorageService,
    private readonly broadCastService: BroadcastingService,
    private readonly tost: TostbarService,
    private readonly pdfData: PdfDataService
  ) {}

  isLoading: boolean = false;

  async ngOnInit() {
    this.isLoading = true;
    if (this.sidebarSingleFile) {
      // If sidebarSingleFile is set, treat it as the only file in viewlist and open it directly
      this.viewlist = [this.sidebarSingleFile];
      this.viewlist[0]["active"] = true;
      await this.activeFiledata(); // Ensure activeFile and cPath are set
    }
    if (this.isRealtime) {
      // Only load a file if tabBox is already set. Otherwise, wait for
      // ngOnChanges → changePdfFile when a hyperlink click sets tabBox.
      if (this.tabBox && this.tabBox.cTab) {
        this.activeFiledata();
      }
    }
    this.updatePath();
    if (this.isLink == 'F' || this.isLink == 'D') {
      this.hidemsg = true;
    }
  }


  async openDocumentInChooser(x) {
    const files: DocumentTab[] = await this.individualService.getTabinfo([x.nBundledetailid]);
    this.OnFileSelected.emit(files);
  }

  ngOnDestroy(): void {
    this.activeFile = null;
    this.cf.openedWindow = null;
  }

  ngAfterViewInit(): void {
  }

  async changePdfFile(tabBox) {
    if (this.tabBox && this.tabBox.cTab) {
      try {
        this.isLoading = true;
        this.cdr.detectChanges();
        this.activeFile = await this.myfileS.getFiledata({ cTab: this.tabBox.cTab, nCaseid: this.nCaseid, cType: this.presentSession ? 'P' : 'M' });
        if (this.activeFile) {
          this.activeFile.nPage = this.tabBox.nPageno || 0;
          this.updatePath();
          this.sendMessageToIframe({ event: 'REALTIME-CHANGE-PDF', data: this.activeFile });
        }
      } catch (error) {
        console.error('[PREVIEW] changePdfFile failed:', error);
        this.isLoading = false;
        this.cdr.detectChanges();
      }
    }
  }

  ngOnChanges(changes: SimpleChanges) {

    if (changes['tabBox']) {

      this.changePdfFile(this.tabBox)
      return;
    }
    if (!changes['viewlist'] && changes['nPage'] && !changes['nPage'].firstChange) {
      this.sendMessageToIframe({ event: 'REDIRECT-TO-PAGE', data: { nPage: this.nPage } })
      return;
    }
    this.activeFile = null;
    this.activeFiledata();
    
  }

  async activeFiledata() {
    this.isLoading = true;
    let ind = this.viewlist.findIndex(e => e["active"]);
    if (ind === -1 && this.sidebarSingleFile) {
      // If sidebarSingleFile is set, use it as the active file
      ind = 0;
    }
    if (ind > -1) {
      try {
        this.currentFiletype = this.viewlist[ind];
        if (this.tabBox && this.tabBox.cTab) {
          this.activeFile = await this.myfileS.getFiledata({ cTab: this.tabBox.cTab, nCaseid: this.nCaseid, cType: this.presentSession ? 'P' : 'M' });
        } else {
          const mdl: filedataReq = { nBundledetailid: this.viewlist[ind].nBundledetailid, cType: this.presentSession ? 'P' : 'M' };
          const res: filedataRes = await this.myfileS.getFiledata(mdl);
          res.nBundledetailid = this.viewlist[ind].nBundledetailid;
          this.nPage = this.nPage || this.getPage(this.viewlist[ind].cPageRange);
          this.activeFile = res;
        }
        this.updatePath();
        this.cdr.detectChanges();
      } catch (error) {
        this.isLoading = false;
      }
    }
    this.isLoading = false;
  }

  getPage(pageRange: string): number {
    try {
      const page = Number(pageRange.split('-')[0])
      return page > 0 ? page : this.nPage;
    } catch (error) {
      return this.nPage;
    }
  }

  changeFile(el, x) {
    const ind = this.viewlist.findIndex(e => e["active"]);
    if (ind > -1) {
      this.viewlist[ind]["active"] = false;
    }
    this.viewlist[el]["active"] = true;
    this.currentFiletype = x;
    this.nonsupport = this.isActiveFileSupported();
    this.activeFiledata();
    this.hidemsg = true;
  }


  closeView(i) {
    this.viewlist.splice(i, 1);
    this.activeFile = null;
    if (this.viewlist.length) {
      this.activeFile = this.viewlist[0];
      this.viewlist[0]["active"] = true;
      this.currentFiletype = this.viewlist[0];
    }
    this.hidemsg = true;
  }

  ClsoePreview() {
    this.OnEvent.emit({ event: 'CLOSE', data: null });
  }

  openmodal(flag) {
    if (flag) {
      this.changePreview.emit(flag);
    }
  }


  OnSelected(e: any) {

    this.OnFileSelected.emit(e);

    if (this.isMyfile) {
      let ids = e.map(x => [x['nBundledetailid'], 1])
      window.open(`${location.origin}/individual/doc/${encodeURIComponent(JSON.stringify([ids, this.nCaseid]))}`);
    }

  }


  updatePath() {
    if (this.activeFile) {
      let page = this.nPage || 1;
      if (this.tabBox) {
        page = this.tabBox.nPageno || 1;
      }

      const filter = this.jFilter?.cSearch && this.jFilter.cWithin == 'I' ? JSON.stringify(this.jFilter) : null;
      const path: any = this.cf.senitizeUrl(this.activeFile.cPath, this.activeFile.nBundledetailid,
        this.nCaseid, false, null, page, this.isRealtime, null, null, null, null,
        null, null, null, this.isMyfile, this.activesectiontype, this.nSectionid, null, null, filter);
      if (path != this.cPath) {
        this.cPath = path;
      }
    }
    if (this.cPath) {
      this.isLoaded = true;
      this.isLoading = false;
    }
    this.cdr.detectChanges();
  }

  addDataToSelectedDocs(data: any) {
    data.jLinktype = { type: (data.mode ? data.mode : 'F'), start: (data.start ? data.start : 0), end: (data.end ? data.end : 0), pages: ((data.pages ? [...new Set(data.pages)] : [])) };
    const ind = this.selectedDocuments.findIndex(a => a.nBundledetailid == data.nBundledetailid && (a.mode !== 'P' ? a.mode == data.mode : (a.mode == data.mode && a.start == data.start && a.end == data.end)))
    if (ind == -1) {
      this.selectedDocuments.unshift(data);
    } else {
      this.selectedDocuments[ind] = { ...this.selectedDocuments[ind], ...data };
    }

    //
  }

  closeRealtimePdf() {
    const e: any = { event: PdfEvents.CLOSE_REALTIME, data: null };
    this.OnEvent.emit(e);
  }



  isActiveFileSupported(): boolean {
    if (!this.activeFile?.cFiletype) {
      return false;
    }

    const fileType = this.activeFile.cFiletype.trim().toLowerCase();

    const supportedExtensions = new Set([
      'jpeg', 'jpg', 'png', 'gif', 'bmp', 'svg',
      'mp4', 'avi', 'mov', 'wmv', 'flv',
      'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'msg', 'dwg', 'xlsm',
    ]);

    const isSupported = supportedExtensions.has(fileType);
    return isSupported;
  }

  downloadFile1(cPath, filename) {}

  async downloadFile(cPath: string, filenames: string) {
    try {
      const groupFileName = this.createGroupFileName(filenames);
      const sanitizedFileName = groupFileName.replaceAll(/[<>:"/\\|?*]/g, '_');
      const shortenedFileName = this.shortenFileName(sanitizedFileName, cPath, 50);

      const downloadUrl = `${environment.downloadservice}/download?cPath=${encodeURIComponent(cPath)}&cFilename=${encodeURIComponent(shortenedFileName)}`;

      const link = document.createElement('a');
      link.href = downloadUrl;

      // Add event listeners
      link.addEventListener('load', () => {
        console.log('Download started');
      });

      link.addEventListener('error', () => {
        console.error('Error downloading file');
      });

      // Append the link to the body
      document.body.appendChild(link);

      // Trigger the click event
      link.click();

      // Remove the link from the document
      link.remove();

    } catch (error) {
      console.error('Error initiating download:', error);
    }
  }

  createGroupFileName(fileNames: string): string {
    const fileList = fileNames.split(',').map(f => f.trim());

    if (fileList.length === 1) {
      return fileList[0];
    }

    const firstFileName = fileList[0].split('.')[0]; // Get name without extension
    const extension = fileList[0].split('.').pop();
    const otherFilesCount = fileList.length - 1;

    let groupName = `${firstFileName} and ${otherFilesCount} other${otherFilesCount > 1 ? 's' : ''}`;

    // Shorten if too long
    if (groupName.length > 50) {
      groupName = groupName.substring(0, 47) + '...';
    }

    return `${groupName}.${extension}`;
  }

  sanitizeFileName(fileName: string): string {
    // Remove or replace characters that might cause issues
    return fileName.replaceAll(/[<>:"/\\|?*]/g, '_');
  }

  ensureFileExtension(path: string, extension: string): string {
    if (!(path.toLocaleUpperCase()).endsWith(extension)) {
      return path + extension;
    }
    return path;
  }


  shortenFileName(fileName: string, cPath: string, maxLength: number = 50): string {
    let extension = fileName.split('.').pop();

    // If no extension in filename, extract it from the path
    const pathExtension = cPath.split('.').pop();
    if (extension.toUpperCase() != pathExtension.toUpperCase()) {
      if (pathExtension) {
        extension = pathExtension;
        fileName += `.${extension}`;
      }
    } else if (fileName.split('.').length > 2) {
      // Handle multiple dots in filename
      const parts = fileName.split('.');
      extension = parts.pop();
      fileName = parts.join('.') + '.' + extension;
    } else {
      extension = extension || '';
    }

    const name = fileName.substring(0, fileName.length - extension.length - 1);

    if (name.length + extension.length + 1 <= maxLength) {
      return fileName;
    }

    const halfMax = Math.floor((maxLength - extension.length - 4) / 2);
    const firstHalf = name.slice(0, halfMax);
    const secondHalf = name.slice(-halfMax);

    return `${firstHalf}...${secondHalf}.${extension}`;
  }

  openInOfficeViewer(url: string): void {
    if (/\.(doc|docx|xls|xlsx|ppt|pptx|xlsm)$/i.test(this.activeFile.cPath.toLowerCase())) {
      const officeViewerUrl = `https://view.officeapps.live.com/op/view.aspx?src=${environment.documentStorage}${encodeURIComponent(url)}`;
      window.open(officeViewerUrl, '_blank');
    } else if (/\.(dwg)$/i.test(this.activeFile.cPath.toLowerCase())) {
      this.cf.openHyperLinkFile(this.activeFile.nBundledetailid, this.nCaseid)
      // const officeViewerUrl = `https://sharecad.org/cadframe/load?url=${environment.documentStorage}${encodeURIComponent(url)}`;
      // window.open(officeViewerUrl, '_blank');
    } else if (/\.(msg)$/i.test(this.activeFile.cPath.toLowerCase())) {
      // this.openIndividual(this.activeFile)
      this.cf.openHyperLinkFile(this.activeFile.nBundledetailid, this.nCaseid)
    } else {
      window.open(environment.documentStorage + url, '_blank');
    }
  }


  sendMessageToIframe(data: any) {

    const iframeElement = this.embeddedIframes.find((iframeRef: ElementRef) => {
      return iframeRef.nativeElement.id === `embedded`;
    });
    if (iframeElement) {
      const iframe = iframeElement.nativeElement;
      iframe.contentWindow.postMessage(data, '*'); // Replace '*' with the specific origin if needed
    }
  }

  async directlink() {

    try {
      let selectedFiles: any[] = [];
      selectedFiles.push(this.selectedDocuments[0]);
      if (!selectedFiles.length) return;
      this.OnFileSelected.emit(selectedFiles);
    } catch (error) {
    }
  }

  async sharebundles() {
    let shareids = this.viewlist.map(view => [view.nBundleid, view.nBundledetailid])
    this.OnEvent.emit({ event: 'SHARE', shareids: shareids })
  }

  async handlePageToolLinkEvent(e: pageLinkToolEvent) {

    if (e.event === PdfEvents.CLOSE) {
      this.close();
    }
    else if (e.event === PdfEvents.DIRECT_LINK) {
      
      const res = await this.pdfData.fetchDocInfo(this.activeFile.nBundledetailid);
      this.activeFile = Object.assign(this.activeFile, res);

      const pages = e.data?.linkType == 'C' ? [this.activePage] : (e.data?.pages || []);
      try {

        if (e.data?.linkType == 'D') {
          if (!e.data)
            e.data = { start: 1, end: 1 };
          if (e.data?.start) {
            e.data.start = 1;
          }
          if (e.data?.end) {
            e.data.end = 1;
          }
          e.data["start"] = res.cPage.split('-')[0]
          e.data["end"] = res.cPage.split('-')[1]
        }
      } catch (error) {

      }
      const data = {
        ...this.activeFile,
        
        mode: e.data?.linkType,
        start: e.data?.linkType == 'C' ? this.activePage : (e.data?.start || 1),
        end: e.data?.linkType == 'C' ? this.activePage : (e.data?.end || 1),
        pages
      }
      this.addDataToSelectedDocs(data);
      this.directlink();
    }
    else if (e.event === PdfEvents.TEXT_SELECTED) {
      console.log('TEXT-SELECTED', this.pageRangeTextSelectionData);
      
      const page = this.pageRangeTextSelectionData?.pages[0]
      const data = {
        ...this.pageRangeTextSelectionData,
        mode: this.pageRangeTextSelectionData?.mode,
        start: page,
        end: page,
      }

      this.addDataToSelectedDocs(data);
      this.directlink();
    }
  }

  close() {
    this.OnCloseEvent.emit();
  }

  pageRangeTextSelection(data: DocInfo) {
    this.pageRangeTextSelectionData = data;
    this.cdr.detectChanges();
  }



}