import { ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { MatRadioModule } from '@angular/material/radio';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { FormsModule } from '@angular/forms';
import { pageLinkToolEvent } from '../../../interfaces/preview.interface';
import { PreviewPageRangeComponent } from "../preview-page-range/preview-page-range.component";
import { filedataRes } from '../../../interfaces/myfile.interface';
import { hightlightModeType } from '../../../../rt/interfaces/feed.interface';
import { pageRangeSelector, PageRangeToolComponent, PageSelection } from "../../../../userpanel/components/individual/page-range-tool/page-range-tool.component";
import { DocInfo } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'page-link-tool',
  standalone: true,
  imports: [MatRadioModule, ButtonComponent, IconComponent, FormsModule, PreviewPageRangeComponent, PageRangeToolComponent],
  templateUrl: './page-link-tool.component.html',
  styleUrl: './page-link-tool.component.scss'
})
export class PageLinkToolComponent {

  linkType: 'D' | 'P' | 'C' = 'C';

  confirmcancel: boolean = false;

  @Input() activeFile: filedataRes;
  @Input() nCaseid: string;
  @Input() nSectionid: string;

  @Output() pageToolEventEmitter = new EventEmitter<pageLinkToolEvent>();

  enablePageRange: boolean = false;
  @Input() hightlightMode: hightlightModeType;
  @Input() pageRangeTextSelectionData: DocInfo;
  pageRangeSelector: pageRangeSelector = null;

  constructor(private cdr: ChangeDetectorRef) { }

  async submit() {
    if (this.linkType == 'P') {
      this.pageRangeSelector = { cPage: this.activeFile?.cPage };
      this.enablePageRange = true;
      this.cdr.detectChanges();
    }
    else {
      this.pageToolEventEmitter.emit({ event: 'DIRECT-LINK', data: { linkType: this.linkType } });
    }

  }

  close() {
    this.pageToolEventEmitter.emit({ event: 'CLOSE', data: null });
  }

  onPageRangeToolEvent(event: PageSelection) {
    this.pageToolEventEmitter.emit({ event: 'DIRECT-LINK', data: { linkType: event.linkType, start: event.startPage, end: event.endPage } });
  }

  onEmitEvent(e: pageLinkToolEvent) {
    this.pageToolEventEmitter.emit(e);
  }
}
